//! Oracle probe for annotate-snippets =0.12.16 (rustc's features: `std` + `simd`).
//!
//! Reads a JSON corpus of render cases on stdin (generated by `corpus.ts` next to this file; the
//! schema is documented there) and prints one JSON line per case:
//!
//!   {"plain": <Renderer::plain() output or null>, "styled": <Renderer::styled() output or null>}
//!
//! Both renderers get the case's `term_width`, `anonymized_line_numbers`, `decor_style` and
//! `short_message` (the options rustc's `AnnotateSnippetEmitter::renderer` sets). `null` means
//! the render panicked (built --release, like rustc: no overflow checks).
use std::io::{Read, Write};
use std::panic;

use annotate_snippets::renderer::DecorStyle;
use annotate_snippets::{
    Annotation, AnnotationKind, Element, Group, Level, Origin, Padding, Patch, Renderer, Snippet,
};
use serde_json::Value;

fn s(v: &Value) -> String {
    v.as_str().expect("string").to_owned()
}

fn n(v: &Value) -> usize {
    v.as_u64().expect("number") as usize
}

fn level(v: &Value) -> Level<'static> {
    let base = match v["l"].as_str().unwrap() {
        "ERROR" => Level::ERROR,
        "WARNING" => Level::WARNING,
        "INFO" => Level::INFO,
        "NOTE" => Level::NOTE,
        "HELP" => Level::HELP,
        x => panic!("bad level {x}"),
    };
    match v.get("name") {
        None => base,
        Some(Value::Null) => base.no_name(),
        Some(x) => base.with_name(s(x)),
    }
}

fn element(e: &Value) -> Element<'static> {
    match e["t"].as_str().unwrap() {
        "message" => level(&e["level"]).message(s(&e["text"])).into(),
        "cause" => {
            let mut sn = Snippet::source(s(&e["source"]));
            if let Some(p) = e.get("path") {
                sn = sn.path(s(p));
            }
            if let Some(l) = e.get("line_start") {
                sn = sn.line_start(n(l));
            }
            if let Some(f) = e.get("fold") {
                sn = sn.fold(f.as_bool().unwrap());
            }
            for a in e["anns"].as_array().unwrap() {
                let kind = match a["kind"].as_str().unwrap() {
                    "Primary" => AnnotationKind::Primary,
                    "Context" => AnnotationKind::Context,
                    "Visible" => AnnotationKind::Visible,
                    x => panic!("bad kind {x}"),
                };
                let mut ann: Annotation<'static> = kind.span(n(&a["start"])..n(&a["end"]));
                if let Some(l) = a.get("label") {
                    ann = ann.label(s(l));
                }
                if let Some(h) = a.get("hl") {
                    ann = ann.highlight_source(h.as_bool().unwrap());
                }
                sn = sn.annotation(ann);
            }
            sn.into()
        }
        "suggestion" => {
            let mut sn = Snippet::source(s(&e["source"]));
            if let Some(p) = e.get("path") {
                sn = sn.path(s(p));
            }
            if let Some(l) = e.get("line_start") {
                sn = sn.line_start(n(l));
            }
            if let Some(f) = e.get("fold") {
                sn = sn.fold(f.as_bool().unwrap());
            }
            for p in e["patches"].as_array().unwrap() {
                sn = sn.patch(Patch::new(n(&p["start"])..n(&p["end"]), s(&p["rep"])));
            }
            sn.into()
        }
        "origin" => {
            let mut o = Origin::path(s(&e["path"]));
            if let Some(l) = e.get("line") {
                o = o.line(n(l));
            }
            if let Some(c) = e.get("col") {
                o = o.char_column(n(c));
            }
            o.into()
        }
        "padding" => Padding.into(),
        x => panic!("bad element {x}"),
    }
}

fn group(g: &Value) -> Group<'static> {
    let mut grp = match g.get("title") {
        Some(t) if !t.is_null() => {
            let lv = level(&t["level"]);
            let mut title = if t["secondary"].as_bool().unwrap_or(false) {
                lv.secondary_title(s(&t["text"]))
            } else {
                lv.primary_title(s(&t["text"]))
            };
            if let Some(id) = t.get("id") {
                title = title.id(s(id));
            }
            if let Some(url) = t.get("url") {
                title = title.id_url(s(url));
            }
            Group::with_title(title)
        }
        _ => Group::with_level(level(&g["level"])),
    };
    for e in g["elements"].as_array().unwrap() {
        grp = grp.element(element(e));
    }
    grp
}

fn configure(r: Renderer, o: &Value) -> Renderer {
    let mut r = r;
    if let Some(w) = o.get("term_width") {
        r = r.term_width(n(w));
    }
    if let Some(a) = o.get("anon") {
        r = r.anonymized_line_numbers(a.as_bool().unwrap());
    }
    if let Some(d) = o.get("decor") {
        r = r.decor_style(match d.as_str().unwrap() {
            "Ascii" => DecorStyle::Ascii,
            "Unicode" => DecorStyle::Unicode,
            x => panic!("bad decor {x}"),
        });
    }
    if let Some(sm) = o.get("short") {
        r = r.short_message(sm.as_bool().unwrap());
    }
    r
}

fn main() {
    let mut input = String::new();
    std::io::stdin().read_to_string(&mut input).unwrap();
    let corpus: Value = serde_json::from_str(&input).unwrap();
    let cases = corpus.as_array().unwrap();

    panic::set_hook(Box::new(|_| {}));
    let stdout = std::io::stdout();
    let mut out = std::io::BufWriter::new(stdout.lock());
    for case in cases {
        let report: Vec<Group<'static>> = case["groups"].as_array().unwrap().iter().map(group).collect();
        let opts = &case["opts"];
        let mut line = serde_json::Map::new();
        for (key, base) in [("plain", Renderer::plain()), ("styled", Renderer::styled())] {
            let r = configure(base, opts);
            let res = panic::catch_unwind(panic::AssertUnwindSafe(|| r.render(&report)));
            line.insert(key.to_owned(), match res {
                Ok(x) => Value::String(x),
                Err(_) => Value::Null,
            });
        }
        writeln!(out, "{}", Value::Object(line)).unwrap();
    }
}
